    # Cache inspect.signature for the wrapper closure to avoid calling it at every decorated invocation.
    # This is separate sig_cache created per decoration, i.e. each function decorated using apply_defaults will
    # have a different sig_cache.
    sig_cache = inspect.signature(func)

    # Identify non-optional arguments in the function's signature that do not have a default value
    # and are not 'self' or keyword-only parameters.
    non_optional_args = {name for (name, param) in sig_cache.parameters.items() if param.default == param.empty and param.name != 'self' and param.kind not in (param.VAR_POSITIONAL, param.VAR_KEYWORD)}

    @wraps(func)
    def wrapper(*args, **kwargs):
        # If the function is called with keyword arguments, use them to set default values for the non-optional arguments.
        if len(args) > 1:
            raise AirflowException("Use keyword arguments when initializing operators")

