def _get_init_containers(self):
    if not (self.kube_config.dags_volume_claim or self.kube_config.dags_volume_host or self.kube_config.dags_in_image):
        return []

    init_environment = [
        {'name': 'GIT_SYNC_REPO', 'value': self.kube_config.git_repo},
        {'name': 'GIT_SYNC_BRANCH', 'value': self.kube_config.git_branch},
        {'name': 'GIT_SYNC_ROOT', 'value': self.kube_config.git_sync_root},
        {'name': 'GIT_SYNC_DEST', 'value': self.kube_config.git_sync_dest},
        {'name': 'GIT_SYNC_DEPTH', 'value': '1'},
        {'name': 'GIT_SYNC_ONE_TIME', 'value': 'true'}
    ]

    if self.kube_config.git_user:
        init_environment.append({'name': 'GIT_SYNC_USERNAME', 'value': self.kube_config.git_user})

    if self.kube_config.git_password:
        init_environment.append({'name': 'GIT_SYNC_PASSWORD', 'value': self.kube_config.git_password})

