    if self._conf:
        for conf_el in self._conf.split(","):
            connection_cmd.append("--conf", conf_el)
    if self._total_executor_cores:
        connection_cmd.append("--total-executor-cores", str(self._total_executor_cores))
    if self._executor_cores:
        connection_cmd.append("--executor-cores", str(self._executor_cores))
    if self._executor_memory:
