    if self._keytab:
        connection_cmd.append("--keytab", self._keytab)
    if self._principal:
        connection_cmd.append("--principal", self._principal)
    if self._num_executors:
        connection_cmd.append("--num-executors", str(self._num_executors))
    if self._sql:
        sql = self._sql.strip()
        if sql.endswith(".sql") or sql.endswith(".hql"):
            connection_cmd.append("-f", sql)
        else:
            connection_cmd.append("-e", sql)
    if self._master:
        connection_cmd.append("--master", self._master)
    if self._name:
        connection_cmd.append("--name", self._name)
    if self._verbose:
        connection_cmd.append("--verbose")
    if self._yarn_queue:
        connection_cmd.append("--queue", self._yarn_queue)
    connection_cmd += cmd
    self.log.debug("Spark-Sql cmd: %s", connection_cmd)
    return connection_cmd
