def build_kalman_mean_step(get_transition_matrix_for_timestep, get_transition_noise_for_timestep, get_observation_matrix_for_timestep, get_observation_noise_for_timestep):
    def mean_step(previous_means, t):
        """Single step of prior mean recursion."""
        previous_latent_mean, _ = previous_means
        latent_mean = _propagate_mean(previous_latent_mean, get_transition_matrix_for_timestep(t - 1), get_transition_noise_for_timestep(t - 1))
        observation_mean = _propagate_mean(latent_mean, get_observation_matrix_for_timestep(t), get_observation_noise_for_timestep(t))
        return (latent_mean, observation_mean)
    return mean_step
