def build_kalman_cov_step(get_transition_matrix_for_timestep, get_transition_noise_for_timestep, get_observation_matrix_for_timestep, get_observation_noise_for_timestep):
    def cov_step(previous_covs, t):
        """Single step of prior covariance recursion."""
        previous_latent_cov, _ = previous_covs
        latent_cov = _propagate_cov(previous_latent_cov, get_transition_matrix_for_timestep(t - 1), get_transition_noise_for_timestep(t - 1))
        observation_cov = _propagate_cov(latent_cov, get_observation_matrix_for_timestep(t), get_observation_noise_for_timestep(t))
        return (latent_cov, observation_cov)
    return cov_step
