def add_headers(self, request):
    # Adds custom properties if self.custom_properties is not empty
    if self.custom_properties:
        for name, value in self.custom_properties.items():
            request.headers.append((name, self._serialize_escaped_properties_value(value)))

    # Adds content-type to the request headers
    request.headers.append(('Content-Type', self.type))

    # Adds BrokerProperties if self.broker_properties is not empty
    if self.broker_properties:
        if hasattr(self.broker_properties, 'items'):
            # Convert BrokerProperties to a dictionary
            broker_properties = {name: self._serialize_basic_properties_value(value) for name, value in self.broker_properties.items()}
            # Convert the dictionary to a JSON string
            broker_properties = json.dumps(broker_properties)
        else:
            # Use the broker_properties as is
            broker_properties = self.broker_properties
        # Append BrokerProperties to the request headers
        request.headers.append(('BrokerProperties', str(broker_properties)))

    # Return the updated request headers
    return request.headers
```

