async def read(self, keys: List[str]) -> dict:
    try:
        # Check if the database and container exist and create if not
        if not self.__container_exists:
            self.__create_db_and_container()

        # Create the parameters object
        parameters = [
            {'name': f'@id{i}', 'value': f'{self.__sanitize_key(key)}'} for i, key in enumerate(keys)
        ]

        # Get the names of the params
        parameter_sequence = ','.join(param.get('name') for param in parameters)

        # Create the query
        query = {
            "query": f"SELECT c.id, c.realId, c.document, c._etag \
            FROM c WHERE c.id in ({parameter_sequence})",
            "parameters": parameters
        }
        options = {'enableCrossPartitionQuery': True}

        # Run the query and store the results as a list
