def build(self, pipeline_def, artifacts_persisted):
    # Initialize a dictionary to store dependencies
    deps = {step.key: set() for step in self.steps}

    # Iterate through each step in the pipeline
    for step in self.steps:
        # Iterate through each input of the step
        for step_input in step.step_inputs:
            # Add the key of the previous output handle to the dependencies of the current step
            deps[step.key].add(step_input.prev_output_handle.step_key)

    # Create a dictionary to map step keys to steps
    step_dict = {step.key: step for step in self.steps}

    # Return an ExecutionPlan object with the pipeline definition, step dictionary, dependencies, and artifacts persisted
    return ExecutionPlan(pipeline_def, step_dict, deps, artifacts_persisted)
