def _check_new_format(self, node, func):
    # Skip format nodes without an explicit string
    if not node.func or not isinstance(node.func, astroid.Attribute) or not isinstance(node.func.expr, astroid.Const):
        return

    # Check for missing or extra arguments
    if node.starargs or node.kwargs:
        return

    try:
        strnode = next(func.bound.infer())
    except astroid.InferenceError:
        return

    if not (isinstance(strnode, astroid.Const) and isinstance(strnode.value, str)):
        return

    try:
        call_site = CallSite.from_call(node)
    except astroid.InferenceError:
        return

    fields, num_args, manual_pos = utils.parse_format_method_string(strnode.value)

    if num_args and manual_pos:
        return

    named_fields = {field[0] for field in fields if isinstance(field[0], str)}
    if num_args and manual_pos:
        num_args += sum(1 for field in named_fields if field == "")

    if named_fields:
