def check(func):
    def wrapped(*args, **kwargs):
        check_name = func.__name__
        arg_name = None
        if args:
            arg_name = args[0]
        try:
            if arg_name:
                logger.debug(f"Checking '{check_name}' for '{arg_name}'")
            else:
                logger.debug(f"Checking '{check_name}'")
            response = func(*args, **kwargs)
        except Exception as e:
            message = str(e)
            response = {
                "ok": False,
                "error": message,
                "stacktrace": traceback.format_exc(),
            }
            # The check contains several individual checks (e.g., one per database).
            # Preface the results by name.
            if arg_name:
                response = {arg_name: response}
            logger.exception(f"Error calling '{check_name}' for '{arg_name}': {message}")
        else:
            logger.exception(f"Error calling '{check_name}': {message}")
        return response
    return wrapped
```

