            if not hasattr(self, attr):
                raise tp(msg)
            return func(self, *args, **kwargs)
        if inspect.iscoroutinefunction(func):
            @functools.wraps(func)
            async def decorated(*args, **kwargs):
                return await decorated(*args, **kwargs)
        return decorated
    return decorator
