                for element in data[file_path]:
                    if data[file_path][element]:
                        PyFunceble.INTERN["mined"][file_path][element] = data[file_path][element]

        # Return the mined data
        return
    else:
        # Return an empty mined dictionary if mining is not activated
        PyFunceble.INTERN["mined"] = {}
        return
