def create_symmetric_key(self, algorithm, length):
    if algorithm not in self._symmetric_key_algorithms.keys():
        raise exceptions.InvalidField("The cryptographic algorithm {0} is not a supported symmetric key algorithm.".format(algorithm))
    cryptography_algorithm = self._symmetric_key_algorithms.get(algorithm)
    if length not in cryptography_algorithm.key_sizes:
        raise exceptions.InvalidField("The cryptographic length ({0}) is not valid for the cryptographic algorithm ({1}).".format(length, algorithm.name))
    self.logger.info("Generating a {0} symmetric key with length: {1}".format(algorithm.name, length))
    key_bytes = os.urandom(length // 8)
    try:
        cryptography_algorithm(key_bytes)
    except Exception as e:
        self.logger.exception(e)
        raise exceptions.CryptographicFailure("Invalid bytes for the provided cryptographic algorithm.")
    return {'value': key_bytes, 'format': enums.KeyFormatType.RAW}
```

```python
def _encrypt_symmetric(self, encryption_algorithm, encryption_key, plain_text, cipher_mode=None, padding_method=None, iv_nonce=None):
    # Set up the algorithm
    algorithm = self._symmetric_key_algorithms.get(encryption_algorithm, None)
    if algorithm is None:
        raise exceptions.InvalidField("Encryption algorithm '{0}' is not a supported symmetric encryption algorithm.".format(encryption_algorithm))
    try:
        algorithm = algorithm(encryption_key)
    except Exception as e:
        self.logger.exception(e)
        raise exceptions.CryptographicFailure("Invalid key bytes for the specified encryption algorithm.")

    # Set up the cipher mode if needed
    return_iv_nonce = False
    if encryption_algorithm == enums.CryptographicAlgorithm.RC4:
        mode = None
    else:
        if cipher_mode is None:
            raise exceptions.InvalidField("Cipher mode is required.")
        mode = self._modes.get(cipher_mode, None)
        if mode is None:
            raise exceptions.InvalidField("Cipher mode '{0}' is not a supported mode.".format(cipher_mode))

    if hasattr(mode, 'initialization_vector') or hasattr(mode, 'nonce'):
        if iv_nonce is None:
            iv_nonce = os.urandom(algorithm.block_size // 8)
        return_iv_nonce = True
        mode = mode(iv_nonce)
    else:
        mode = mode()

    # Pad the plain text if needed
    if cipher_mode in [enums.BlockCipherMode.CBC, enums.BlockCipherMode.ECB]:
        plain_text = self._handle_symmetric_padding(self._symmetric_key_algorithms.get(encryption_algorithm), plain_text, padding_method)

    # Encrypt the plain text
    cipher = ciphers.Cipher(algorithm, mode, backend=default_backend())
    encryptor = cipher.encryptor()
    cipher_text = encryptor.update(plain_text) + encryptor.finalize()

    if return_iv_nonce:
        return {'cipher_text': cipher_text, 'iv_nonce': iv_nonce}
    else:
        return {'cipher_text': cipher_text}
```

```python
def _encrypt_asymmetric(self, encryption_algorithm, encryption_key, plain_text, padding_method, hashing_algorithm=None):
    if encryption_algorithm == enums.CryptographicAlgorithm.RSA:
        if padding_method == enums.PaddingMethod.OAEP:
            if hashing_algorithm is None:
                raise exceptions.InvalidField("The hashing algorithm '{0}' is not supported for asymmetric encryption.".format(hashing_algorithm))
            padding_method = asymmetric_padding.OAEP(mgf=asymmetric_padding.MGF1(algorithm=hashing_algorithm()), algorithm=hashing_algorithm(), label=None)
        elif padding_method == enums.PaddingMethod.PKCS1v15:
            padding_method = asymmetric_padding.PKCS1v15()
        else:
            raise exceptions.InvalidField("The padding method '{0}' is not supported for asymmetric encryption.".format(padding_method))
    else:
        raise exceptions.InvalidField("The cryptographic algorithm '{0}' is not supported for asymmetric encryption.".format(encryption_algorithm))

    backend = default_backend()
    try:
        public_key = backend.load_der_public_key(encryption_key)
    except Exception:
        try:
            public_key = backend.load_pem_public_key(encryption_key)
        except Exception:
            raise exceptions.CryptographicFailure("The public key bytes could not be loaded.")

    cipher_text = public_key.encrypt(plain_text, padding_method)
    return {'cipher_text': cipher_text}
```

```python
def _create_rsa_key_pair(self, length, public_exponent=65537):
    self.logger.info("Generating an RSA key pair with length: {0}, and public_exponent: {1}".format(length, public_exponent))
    try:
        private_key = rsa.generate_private_key(public_exponent=public_exponent, key_size=length, backend=default_backend())
        public_key = private_key.public_key()
        private_bytes = private_key.private_bytes(serialization.Encoding.DER, serialization.PrivateFormat.PKCS8, serialization.NoEncryption())
        public_bytes = public_key.public_bytes(serialization.Encoding.DER, serialization.PublicFormat.PKCS1)
    except Exception as e:
        self.logger.exception(e)
        raise exceptions.CryptographicFailure("An error occurred while generating the RSA key pair. See the server log for more information.")
    public_key = {'value': public_bytes, 'format': enums.KeyFormatType.PKCS_1, 'public_exponent': public_exponent}
    private_key = {'value': private_bytes, 'format': enums.KeyFormatType.PKCS_8, 'public_exponent': public_exponent}
    return public_key, private_key
```

