def _interpret_response(self, response, payload, expected_status):
    # Extract the raw content from the response
    raw_content = response.text
    if not raw_content:
        raise with_context(
            exc=BadApiResponse(
                'Empty {status} response from node.'.format(status=response.status_code),
                context={'request': payload},
            ),
        )

    try:
        # Attempt to decode the raw content as JSON
        decoded = json.loads(raw_content)
    except ValueError:
        raise with_context(
            exc=BadApiResponse(
                'Non-JSON {status} response from node: {raw_content}'.format(
                    status=response.status_code,
                    raw_content=raw_content,
                ),
                context={'request': payload, 'raw_response': raw_content},
            ),
        )

    if not isinstance(decoded, dict):
        raise with_context(
            exc=BadApiResponse(
                'Malformed {status} response from node: {decoded!r}'.format(
                    status=response.status_code,
                    decoded=decoded,
                ),
                context={'request': payload, 'response': decoded},
            ),
        )

    if response.status_code in expected_status:
        return decoded

    error = None
    try:
        # Check for specific error codes
        if response.status_code == codes['bad_request']:
            error = decoded['error']
        elif response.status_code == codes['internal_server_error']:
            error = decoded['exception']
    except KeyError:
        pass

    raise with_context(
        exc=BadApiResponse(
            '{status} response from node: {error}'.format(
                error=error or decoded,
                status=response.status_code,
            ),
            context={'request': payload, 'response': decoded},
        ),
    )
```

