def discover_commands(package, recursively=True):  # type: (Union[ModuleType, Text], bool) -> Dict[Text, 'CommandMeta']
    # Import the package if it's a string
    if isinstance(package, str):
        package = import_module(package)

    # Initialize an empty dictionary to store command metadata
    commands = {}

    # Walk through the package's sub-packages
    for _, name, is_package in walk_packages(package.__path__, package.__name__ + '.'):
        # Import the sub-package
        sub_package = import_module(name)

        # Iterate through the members of the sub-package
        for _, obj in get_members(sub_package):
            # Check if the object is a class and a CommandMeta subclass
            if is_class(obj) and isinstance(obj, CommandMeta):
                # Get the command name from the class
                command_name = getattr(obj, 'command')

                # If a command name is found, add it to the commands dictionary
                if command_name:
                    commands[command_name] = obj

    # If recursively discovering commands is enabled and the sub-package is a package, discover commands in the sub-package
    if recursively and is_package:
        commands.update(discover_commands(sub_package))

    # Return the dictionary of command metadata
    return commands
