def normal_name(self, rm_namespaces=('Template',), capitalize_links=False, code=None, *, code=None, capitalize=False) -> str:
    if capitalize_links:
        warnings.warn("`capital_links` argument is deprecated, use `capitalize` instead", DeprecationWarning)
    capitalize = capitalize_links if code is None else capitalize

    if code is not None:
        warnings.warn("`positional_code` argument is deprecated, use `code` instead", DeprecationWarning)
    code = code

    # Remove comments
    name = COMMENT_SUB('', self.name).strip(WS)

    # Remove code if present
    if code:
        head, sep, tail = name.partition(':')
        if not head and sep:
            name = tail.strip(' ')
        head, sep, tail = name.partition(':')
        if code.lower() == head.strip(' ').lower():
            name = tail.strip(' ')

    # Remove namespace
    head, sep, tail = name.partition(':')
    if not head and sep:
        name = tail.strip(' ')
    head, sep, tail = name.partition(':')
    for namespace in rm_namespaces:
        if namespace.lower() == head.strip(' ').lower():
            name = tail.strip(' ')
            break

    # Use space instead of underscore
    name = name.replace('_', ' ')

    # Capitalize the first letter if specified
    if capitalize:
        n0 = name[0]
        if n0.islower():
            name = n0.upper() + name[1:]

    # Remove #anchor
    name, sep, tail = name.partition('#')
    return ' '.join(name.split())
