                    if k[0] == '_' or not v:
                        continue
                    if all(not x for x in v):
                        continue
                    metadata[k] = v
                    if sm.used_setuptools:
                        for extras in ['cmdclass', 'zip_safe', 'test_suite']:
                            v = getattr(distro, extras, None)
                            if v is not None and v not in ([], {}):
