def process_text_constructor(cleaner:Callable, tokenizer:Callable, append_indicators:bool, start_tok:str, end_tok:str):
    def process_text(text):
        if append_indicators:
            return [[start_tok] + tokenizer(cleaner(doc)) + [end_tok] for doc in text]
