def equals_order_sensitive(self, other):
    # Check if the other object is a mapping and has the same length as the current object
    if not isinstance(other, Mapping) or len(self) != len(other):
        return False
    # Compare each key-value pair in the current object with the corresponding key-value pair in the other object
    return all(i == j for (i, j) in izip(iteritems(self), iteritems(other)))
