def wrap_non_picklable_objects(obj, keep_wrapper=True):
    if not cloudpickle:
        raise ImportError("could not import cloudpickle. Please install cloudpickle to allow extended serialization. (`pip install cloudpickle`).")
    if inspect.isclass(obj):
