def arg_split(s, posix=False):
    args_list = [[]] if isinstance(s, bytes) else s.decode("utf-8")
    lex = shlex.shlex(s, posix=posix)
    lex.whitespace_split = True
    args = list(lex)
    for arg in args:
        if ';;' == arg:
            args_list.append([])
        else:
            args_list[-1].append(arg)
    return args_list
