def _addHdlProcToRun(self, trigger:SimSignal, proc):
    # If the process is the first one in time, it should plan executing apply values on the end of this time.
    # If not, it schedules the process to be executed.
    if not self._applyValPlaned:
        self._scheduleApplyValues()

    # If the trigger is dependent on the process, it should be added to the sequence of processes to run.
    # Otherwise, it should be added to the combination of processes to run.
    if isEvDependentOn(trigger, proc):
        self._seqProcsToRun.append(proc)
    else:
        self._combProcsToRun.append(proc)
