def map_words(self, start, end):
    i, j = 8 * start - 8, 8 * end
    try:
        fileno = self.file.fileno()
    except (AttributeError, io.UnsupportedOperation):
        fileno = None
    if fileno is None:
        skip = 0
    else:
        skip = i % mmap.ALLOCATIONGRANULARITY
    m = mmap.mmap(fileno, length=j - i + skip, access=mmap.ACCESS_READ, offset=i - skip)
    if sys.version_info > (3,):
        m = memoryview(m)
    return m, skip
