def timer_decorator(self, stat, tags=None):
    def _inner(fun):
        @wraps(fun)
        def _timer_decorator(*args, **kwargs):
            with self.timer(stat, tags):
                return fun(*args, **kwargs)
        return _timer_decorator
    return _inner
```

