def set_compiler_channels(self, channel_list, operator="mix"):
    if not channel_list:
        raise eh.ProcessError("At least one status channel must be provided to include this process in the pipeline")
    if len(channel_list) == 1:
        logger.debug("Setting only one status channel: {}".format(channel_list[0]))
        self._context = {"compile_channels": channel_list[0]}
    else:
        first_status = channel_list[0]
        if operator == "mix":
            lst = ",".join(channel_list[1:])
            s = "{}.mix({})".format(first_status, lst)
        elif operator == "join":
            s = first_status
