def get_lanes(lanes_str):
    logger.debug("Parsing lanes from raw string: {}".format(lanes_str))
    parsed_lanes = ""
    infork = 0
    for i in lanes_str:
        if i == FORK_TOKEN:
            infork += 1
        elif i == CLOSE_TOKEN:
            infork -= 1
        if infork < 0:
            break
        if infork == 0:
            if i not in [FORK_TOKEN, CLOSE_TOKEN]:
                parsed_lanes += i
    return [x.split() for x in parsed_lanes.split(LANE_TOKEN)]
