def linear_connection(plist, lane):
    logger.debug("Establishing linear connection with processes: {}".format(plist))
    res = []
    previous = None
    for p in plist:
        if previous is not None:
            res.append({
                "input": {"process": previous, "lane": lane},
                "output": {"process": p, "lane": lane}
            })
        previous = p
    return res
