```python
def fork_connection(source, sink, source_lane, lane):
    logger.debug("Establishing forking of source '{}' into processes '{}'".format(source, sink))
    res = []
    lane_counter = lane + 1
    for p in sink:
        res.append({
            "input": {
                "process": source,
                "lane": source_lane
            },
            "output": {
                "process": p,
                "lane": lane_counter
            }
        })
        lane_counter += 1
    return res
```

