def _get_params_string(self):
    params_str = ""
    for p in self.processes:
        logger.debug("[{}] Adding parameters: {}\n".format(p.template, p.params))
        # Add an header with the template name to structure the params configuration
        if p.params and p.template != "init":
            p.set_param_id("_{}".format(p.pid))
        params_str += "\n\t/*"
        params_str += "\n\tComponent '{}_{}'\n".format(p.template, p.pid)
        params_str += "\t{}\n".format("-" * (len(p.template) + len(p.pid) + 12))
        params_str += "\t*/\n"
        for param, val in p.params.items():
            if p.template == "init":
                param_id = param
            else:
                param_id = "{}_{}".format(param, p.pid)
            params_str += "\t{} = {}\n".format(param_id, val["default"])
    return params_str
```

