def activate_async(fn, _engine):
    @coroutine
    @functools.wraps(fn)
    def wrapper(*args, **kw):
        _engine.activate()
        try:
            if iscoroutinefunction(fn):
                yield from fn(*args, **kw)
            else:
                fn(*args, **kw)
        finally:
            _engine.disable()
    return wrapper
