def facets(self, *args, **kwargs):
    # Combine args and kwargs into facet format
    facets = dict((a, {}) for a in args)
    facets.update(kwargs)
    if not facets:
        raise AttributeError('Faceting requires at least one field')
    for f in facets.keys():
