def hgnc_genes(self, hgnc_symbol, build='37', search=False):
    """Fetches genes with the given HGNC symbol. If a full match is found, it returns the full query result. Otherwise, it performs a case-insensitive search for the symbol and returns the matching results. The search is limited to the specified build."""
    LOG.debug(f"Fetching genes with symbol {hgnc_symbol}")
    if search:
        # First search for a full match
        full_query = self.hgnc_collection.find({
            '$or': [
                {'aliases': hgnc_symbol},
                {'hgnc_id': int(hgnc_symbol) if hgnc_symbol.isdigit() else None},
            ],
            'build': build
        })
        if full_query.count() != 0:
            return full_query
    # Perform a case-insensitive search
    return self.hgnc_collection.find({
        'aliases': {'$regex': hgnc_symbol, '$options': 'i'},
        'build': build
    })
