def _build_dummy_calls(self):
    dummy_calls = []
    for d in self.kernel_ast.block_items:
        if type(d) is not c_ast.Decl:
            continue
        if type(d.type) is c_ast.ArrayDecl:
            dummy_calls.append(c_ast.FuncCall(c_ast.ID('dummy'), c_ast.ExprList([c_ast.ID(d.name)])))
        else:
            dummy_calls.append(c_ast.FuncCall(c_ast.ID('dummy'), c_ast.ExprList([c_ast.UnaryOp('&', c_ast.ID(d.name))])))
    dummy_stmt = c_ast.If(cond=c_ast.ID('var_false'), iftrue=c_ast.Compound(dummy_calls), iffalse=None)
    return dummy_stmt
```

```python
def _build_scalar_declarations(self, with_init=True):
    # Copy scalar declarations from the kernel AST
    scalar_declarations = [deepcopy(d) for d in self.kernel_ast.block_items if isinstance(d, c_ast.Decl) and isinstance(d.type, c_ast.TypeDecl)]

    # Add initialization values to declarations if with_init is True
    if with_init:
        random.seed(2342)
        for d in scalar_declarations:
            if d.type.type.names[0] in ['double', 'float']:
                d.init = c_ast.Constant('float', str(random.uniform(1.0, 0.1)))
            elif d.type.type.names[0] in ['int', 'long', 'long long', 'unsigned int', 'unsigned long', 'unsigned long long']:
                d.init = c_ast.Constant('int', 2)
    return scalar_declarations
```

