def f_get_from_runs(self, name, include_default_run=True, use_indices=False, fast_access=False, with_links=True, shortcuts=True, max_depth=None, auto_load=False):
    result_dict = OrderedDict()
    old_crun = self.v_crun
    try:
        if len(self._run_parent_groups) > 0:
            for run_name in self.f_iter_runs():
                value = None
                already_found = False
                for run_parent_group in self._run_parent_groups.values():
                    if run_name not in run_parent_group._children:
                        continue
                    try:
                        value = run_parent_group.f_get(run_name + '.' + name, fast_access=False, with_links=with_links, shortcuts=shortcuts, max_depth=max_depth, auto_load=auto_load)
                        if already_found:
                            raise pex.NotUniqueNodeError(f"`{name}` has been found several times in one run.")
                        else:
                            already_found = True
                    except (AttributeError, pex.DataNotInStorageError):
                        pass
                if value is None and include_default_run:
                    for run_parent_group in self._run_parent_groups.values():
                        try:
                            value = run_parent_group.f_get(self.f_wildcard('$', -1) + '.' + name, fast_access=False, with_links=with_links, shortcuts=shortcuts, max_depth=max_depth, auto_load=auto_load)
                            if already_found:
                                raise pex.NotUniqueNodeError(f"`{name}` has been found several times in one run.")
                            else:
                                already_found = True
                        except (AttributeError, pex.DataNotInStorageError):
                            pass
                if value is not None:
                    if value.v_is_leaf:
                        value = self._nn_interface._apply_fast_access(value, fast_access)
                    if use_indices:
                        key = self.f_idx_to_run(run_name)
                    else:
                        key = run_name
                    result_dict[key] = value
    finally:
        self.v_crun = old_crun
