def complete(text: str, kw_cache: atom.Atom["PMap[int, Keyword]"] = __INTERN) -> Iterable[str]:
    assert text.startswith(":")
    interns = kw_cache.deref()
    text = text[1:]
    if "/" in text:
        prefix, suffix = text.split("/", maxsplit=1)
        results = filter(
            lambda kw: (kw.ns is not None and kw.ns == prefix) and kw.name.startswith(suffix),
            interns.itervalues(),
        )
    else:
        results = filter(
            lambda kw: kw.name.startswith(text) or (kw.ns is not None and kw.ns.startswith(text)),
            interns.itervalues(),
        )
    return map(str, results)
```

