def _fn_with_meta(f, meta:Optional[lmap.Map]):
    if not isinstance(meta, lmap.Map):
        raise TypeError("meta must be a map")
    if inspect.iscoroutinefunction(f):
        @functools.wraps(f)
        async def wrapped_f(*args, **kwargs):
            return await f(*args, **kwargs)
    else:
        @functools.wraps(f)
        def wrapped_f(*args, **kwargs):
            return f(*args, **kwargs)
    wrapped_f.meta = (f.meta.update(meta) if hasattr(f, "meta") and isinstance(f.meta, lmap.Map) else meta)
    wrapped_f.with_meta = partial(_fn_with_meta, wrapped_f)
    return wrapped_f
