```python
def __complete_alias(self, prefix: str, name_in_ns: Optional[str] = None) -> Iterable[str]:
    candidates = filter(Namespace.__completion_matcher(prefix), [(s, n) for s, n in self.aliases])
    if name_in_ns is not None:
        for _, candidate_ns in candidates:
            for match in candidate_ns.__complete_interns(name_in_ns, include_private_vars=False):
                yield f"{prefix}/{match}"
    else:
        for alias, _ in candidates:
            yield f"{alias}/"
```

```python
def __complete_imports_and_aliases(self, prefix: str, name_in_module: Optional[str] = None) -> Iterable[str]:
    imports = self.imports
    aliases = lmap.map({alias: imports.entry(import_name) for alias, import_name in self.import_aliases})
    candidates = filter(Namespace.__completion_matcher(prefix), itertools.chain(aliases, imports))

    if name_in_module is not None:
        for _, module in candidates:
            for name in module.__dict__:
                if name.startswith(name_in_module):
                    yield f"{prefix}/{name}"
                else:
                    for candidate_name, _ in candidates:
                        yield f"{candidate_name}/"
```

```python
def __complete_interns(self, value: str, include_private_vars: bool = True) -> Iterable[str]:
    if include_private_vars:
        is_match = Namespace.__completion_matcher(value)
    else:
        is_match = Namespace.__completion_matcher(value)

    def is_match(entry: Tuple[sym.Symbol, Var]) -> bool:
        return is_match(entry) and not entry[1].is_private

    return map(lambda entry: f"{entry[0].name}", filter(is_match, [(s, v) for s, v in self.interns]))
```

```python
def __complete_refers(self, value: str) -> Iterable[str]:
    return map(lambda entry: f"{entry[0].name}", filter(Namespace.__completion_matcher(value), [(s, v) for s, v in self.refers]))
