def _classify_line(cls, line):
    line = line.rstrip()
    if len(line) == 0:
        return BlankLine('')
    if ' ' not in line and line.endswith(':'):
        name = line[:-1]
        return SectionHeader(name)
    if line.startswith('  '):
        return ContinuationLine(line.lstrip())
    if line.startswith(' - '):
        return ListItem('-', line[3:].lstrip())
    if line.startswith(' - '):
        return ListItem('-', line[2:].lstrip())
    return Line(line)
