def _hash(self, regularizers=()):
    h = hashlib.md5()
    for l in self.layers:
        h.update(str(l.__class__.__name__).encode('utf-8'))
        h.update(str(l.name).encode('utf-8'))
        h.update(str(l.output_shape).encode('utf-8'))
    for l in self.losses:
        h.update(str(l.__class__.__name__).encode('utf-8'))
        h.update(str(l.weight).encode('utf-8'))
    for r in regularizers:
        h.update(str(r.__class__.__name__).encode('utf-8'))
        h.update(str(r.weight).encode('utf-8'))
        h.update(str(r.pattern).encode('utf-8'))
    return h.hexdigest()
