    chain_step_bytes = 4
    max_bits_per_step = 2 ** 31
    chain_steps = [int(chain_path[i:i + chain_step_bytes * 2], 16) % max_bits_per_step for i in range(0, len(chain_path), chain_step_bytes * 2)]
