def distutils_scheme(dist_name, user=False, home=None, root=None, isolated=False):
    from distutils.dist import Distribution
    scheme = {}
    if isolated:
        extra_dist_args = {"script_args": ["--no-user-cfg"]}
    else:
        extra_dist_args = {}
    dist_args = {'name': dist_name}
    dist_args.update(extra_dist_args)
    d = Distribution(dist_args)
    d.parse_config_files()
    i = d.get_command_obj('install', create=True)
    i.user = user or i.user
    i.home = home or i.home
    i.root = root or i.root
    i.finalize_options()
    for key in SCHEME_KEYS:
        scheme[key] = getattr(i, 'install_' + key)
    if i.install_lib is not None:
        scheme.update(dict(purelib=i.install_lib, platlib=i.install_lib))
    if running_under_virtualenv():
        scheme['headers'] = os.path.join(sys.prefix, 'include', 'site', 'python' + sys.version[:3], dist_name,)
    if root is not None:
        scheme['headers'] = os.path.join(root, os.path.abspath(scheme['headers'])[1:])
    return scheme
