def enum(*sequential, **named):
    # Build enums from parameter enums = dict(zip(sequential, range(len(sequential))), **named)
    enums = dict(zip(sequential, range(len(sequential))), **named)
    # Build reverse mapping enums['rmap'] = {}
    enums['rmap'] = {}
    # For each key-value pair in enums
    for key, value in enums.items():
        # If the value is an integer
        if type(value) is int:
            # Add the key to the reverse mapping with the value as the key
            enums['rmap'][value] = key
    # Return the Enum class
    return type('Enum', (), enums)
