def __exit_scope(self) -> ast.stmt:
    if self.in_optional:
        return ast.Pass()
    elif self.in_try:
        return ast.Raise(ast.Call(ast.Name('AltFalse', ast.Load()), [], [], None, None))
    elif self.in_loop:
        return ast.Break()
    return ast.Return(ast.Name('False', ast.Load()))
