def _encode_fields(self, xfield, yfield, time_unit=None, scale=None):
    if scale is None:
        scale = Scale(zero=False)
    xfield_type = xfield[1]
    yfield_type = yfield[1]
    x_options = None
    y_options = None

    if len(xfield) > 2:
        x_options = xfield[2]
    if len(yfield) > 2:
        y_options = yfield[2]

    if time_unit is not None:
        if x_options is None:
            xencode = X(xfield_type, timeUnit=time_unit)
        else:
            xencode = X(xfield_type, axis=Axis(*x_options), timeUnit=time_unit, scale=scale)
    else:
        if x_options is None:
            xencode = X(xfield_type)
        else:
            xencode = X(xfield_type, axis=Axis(*x_options), scale=scale)

    if y_options is None:
