def code_unit_factory(morfs, file_locator):
    # Ensure morfs is a list
    if not isinstance(morfs, (list, tuple)):
        morfs = [morfs]

    # On Windows, the shell doesn't expand wildcards. Do it here.
    globbed = []
    for morf in morfs:
        if isinstance(morf, str_class) and ('?' in morf or '*' in morf):
            globbed.extend(glob.glob(morf))
        else:
            globbed.append(morf)

    # Convert the list of globbed paths to CodeUnit objects
    code_units = [CodeUnit(morf, file_locator) for morf in globbed]

    return code_units
