def pkg_commit_hash(pkg_path):
    # Try to get commit from written commit text file if _sysinfo.commit is available
    if _sysinfo.commit:
        return "installation", _sysinfo.commit
    # Otherwise, try to get commit from the repository
    proc = subprocess.Popen('git rev-parse --short HEAD', stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=pkg_path, shell=True)
    repo_commit, _ = proc.communicate()
    if repo_commit:
        return 'repository', repo_commit.strip()
    # If no commit is found, return '(none found)', '<not found>'
    return '(none found)', '<not found>'
