def as_dict(self, attrs=None, ad_value=None):
    excluded_names = {'send_signal', 'suspend', 'resume', 'terminate', 'kill', 'wait', 'is_running', 'as_dict', 'parent', 'get_children', 'nice'}
    ret_dict = {}
    for name in set(attrs or dir(self)):
        if name.startswith('_'):
            continue
        if name.startswith('set_'):
            continue
        if name in excluded_names:
            continue
        try:
            attr = getattr(self, name)
            if callable(attr):
                if name == 'get_cpu_percent':
                    ret = attr(interval=0)
                else:
                    ret = attr()
            else:
                ret = attr
        except AccessDenied:
            ret = ad_value
        except NotImplementedError:
            if attrs:
                raise
        if name.startswith('get'):
            if name[3] == '_':
                name = name[4:]
            elif name == 'getcwd':
                name = 'cwd'
            ret_dict[name] = ret
    return ret_dict
