def countdown(name, date, description='', id='', granularity='sec', start=None, progressbar=False, progressbar_inversed=False, showpct=False):
    end_date = dateparse.parse_datetime(date)
    end = dateformat.format(end_date, 'U')
    content = '<div class="name">' + name + '</div>' + '<div class="description">' + description + '</div>'
    if progressbar:
        if not end:
            raise Exception('For progressbar, start date is required.')
        parsed_date = datetime.datetime.combine(dateparse.parse_date(start), datetime.time())
        start_date = dateparse.parse_datetime(start) or parsed_date
        now = datetime.datetime.now()
        pct = (now - start_date).total_seconds() / (end_date - start_date).total_seconds()
        pct = int(pct * 100)
        if progressbar_inversed:
            pct = 100 - pct
        bar = '<div class="progress progress-striped active">' + \
               '<div class="progress-bar" role="progressbar" aria-valuenow="{pct}" aria-valuemin="0" aria-valuemax="100" style="width: {pct}%">' + \
               '<span class="sr-only">{pct}% Complete</span>' + \
               '</div>' + \
               '</div>'
        if showpct:
            bar += '<div class="percentage">{pct}%</div>'
        bar = bar.format(pct=pct)
        content += bar
        content += '<div class="counter"></div>'
    attr = {'class': 'countdownbox', 'data-datetime': end, 'data-granularity': granularity}
    if id:
        attr['id'] = id
    return html.tag('div', content, attr)
